patch:
diff --git a/repro/issue-18575-windows-other-drive.js b/repro/issue-18575-windows-other-drive.js
new file mode 100644
index 0000000..f04532c
--- /dev/null
+++ b/repro/issue-18575-windows-other-drive.js
@@ -0,0 +1,78 @@
+/**
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ *
+ * SIMULATED Windows: this VM runs Linux, so before loading ESLint we replace
+ * the methods of the shared `node:path` module with `path.win32` and make
+ * `process.cwd()` return a C: directory. Nothing in lib/ is modified.
+ *
+ * Run: node repro/issue-18575-windows-other-drive.js
+ */
+/* eslint-disable no-console -- repro script output */
+"use strict";
+
+const path = require("node:path");
+const win32 = path.win32;
+
+const CWD = "C:\\Project";
+
+/*
+ * Load ESLint (and the lazily loaded rules) before switching `path` to win32,
+ * since Node's own module resolver also uses the shared `path` object.
+ */
+const { Linter, ESLint } = require("../lib/api");
+const builtinRules = require("../lib/rules");
+
+for (const [, rule] of builtinRules) {
+    void rule;
+}
+
+Object.assign(path, win32);
+process.cwd = () => CWD;
+
+const cases = [
+    { file: "C:\\Project\\foo.js", expectIgnored: false, label: "inside cwd (control)" },
+    { file: "C:\\Other\\foo.js", expectIgnored: true, label: "same drive, outside cwd (control)" },
+    { file: "F:\\foo.js", expectIgnored: true, label: "different drive (REPORTED)" }
+];
+
+(async () => {
+    let failures = 0;
+
+    console.log(`simulated cwd: ${process.cwd()}`);
+    for (const { file } of cases) {
+        console.log(`path.relative(${JSON.stringify(CWD)}, ${JSON.stringify(file)}) = ${JSON.stringify(path.relative(CWD, file))}`);
+    }
+
+    for (const { file, expectIgnored, label } of cases) {
+        console.log(`\n=== ${label}: ${file} ===`);
+
+        // 1. Linter (as in the report's "Additional comments")
+        const linter = new Linter({ configType: "flat" });
+        const linterMsgs = linter.verify("foo()", { rules: { "no-undef": "error" } }, file);
+        const linterIgnored = linterMsgs.some(m => m.ruleId === null && /No matching configuration/u.test(m.message)) &&
+            !linterMsgs.some(m => m.ruleId === "no-undef");
+
+        console.log("Linter#verify:", JSON.stringify(linterMsgs.map(m => `${m.ruleId}: ${m.message}`)));
+
+        // 2. ESLint API (what `eslint --no-config-lookup <file>` uses)
+        const eslint = new ESLint({ overrideConfigFile: true, overrideConfig: { rules: { "no-undef": "error" } } });
+        const [result] = await eslint.lintText("foo();\n", { filePath: file, warnIgnored: true });
+        const eslintIgnored = result.messages.some(m => m.ruleId === null && /ignored/u.test(m.message));
+
+        console.log("ESLint#lintText:", JSON.stringify(result.messages.map(m => `${m.ruleId}: ${m.message}`)));
+        console.log("ESLint#isPathIgnored:", await eslint.isPathIgnored(file));
+
+        for (const [api, ignored] of [["Linter", linterIgnored], ["ESLint", eslintIgnored]]) {
+            const ok = ignored === expectIgnored;
+
+            if (!ok) {
+                failures++;
+            }
+            console.log(`${ok ? "OK  " : "BUG "} ${api}: expected ${expectIgnored ? "ignored" : "linted"}, got ${ignored ? "ignored" : "linted"}`);
+        }
+    }
+
+    console.log(`\n${failures} unexpected result(s)`);
+    process.exitCode = failures ? 1 : 0;
+})();
+/* eslint-enable no-console -- end of repro script */
